WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "id" = $1 FROM "public"."mutation_item" AS "b0" WHERE "s"."id" = "b0"."id" AND ( "s"."id" = $2 ) RETURNING "s" AS "t0" , "b0"."ctid" AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ), "w0" AS (SELECT "s" .* FROM "public"."mutation_item" AS "s" WHERE NOT EXISTS ( SELECT 1 FROM "m0" WHERE "m0"."k0" = "s"."ctid" ) UNION ALL SELECT * FROM "r0" ) SELECT json_build_object( 'affected_rows' , (SELECT count(*) FROM "r0" ) , 'returning' , (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "c1"."j" AS "owner" ) AS "%")) ), '[]') FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "c0"."j" AS "items" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" LEFT JOIN LATERAL (SELECT coalesce(json_agg( row_to_json((SELECT "%" FROM (SELECT "t2"."id" AS "id" , "t2"."score" AS "score" ) AS "%")) ORDER BY "t2"."id" ASC NULLS LAST ), '[]') AS "j" FROM ( SELECT "s".* FROM "w0" AS "s" WHERE true AND "s"."owner_id" = "t1"."id" AND ( ( true ) ) ORDER BY "s"."id" ASC NULLS LAST ) AS "t2" ) AS "c0" ON true ) AS "c1" ON true ) )
